203		public async lintHotkey() {
204			const hotkey = await this.actions.getHotkey?.();
205	
206			document.addEventListener(
207				'keydown',
208				(event: KeyboardEvent) => {
209					if (!hotkey) return;
210	
211					const key = event.key.toLowerCase();
212					const expectedKey = hotkey.key.toLowerCase();
213	
214					const hasCtrl = event.ctrlKey === hotkey.modifiers.includes('Ctrl');
215					const hasAlt = event.altKey === hotkey.modifiers.includes('Alt');
216					const hasShift = event.shiftKey === hotkey.modifiers.includes('Shift');
217	
218					const match = key === expectedKey && hasCtrl && hasAlt && hasShift;
219	
220					if (match) {
221						event.preventDefault();
222						event.stopImmediatePropagation();
223	
224						const caretPosition = getCaretPosition();
225	
226						if (caretPosition != null) {
227							const closestIdx = closestBox(caretPosition, this.lastBoxes);
228	
229							const previousBox = this.lastBoxes[closestIdx];
230							const suggestions = previousBox.lint.suggestions;
231							if (suggestions.length > 0) {
232								previousBox.applySuggestion(suggestions[0]);
233							} else {
234								previousBox.ignoreLint?.();
235							}
236						}
237					}
238				},
239				{ capture: true },
240			);
241		}
