266		private attachTargetListeners(target: Node) {
267			for (const event of INPUT_EVENTS) {
268				target.addEventListener(event, this.updateEventCallback);
269			}
270	
271			const observer = new MutationObserver(this.updateEventCallback);
272			const config = { subtree: true, characterData: true };
273	
274			if ((target as any).tagName == undefined) {
275				observer.observe((target as any).parentElement!, config);
276			} else {
277				observer.observe(target as Element, config);
278			}
279	
280			const scrollableAncestors = getScrollableAncestors(target);
281	
282			for (const el of scrollableAncestors) {
283				if (!this.scrollableAncestors.has(el as HTMLElement)) {
284					this.scrollableAncestors.add(el as HTMLElement);
285					(el as HTMLElement).addEventListener('scroll', this.updateEventCallback, {
286						capture: true,
287						passive: true,
288					});
289				}
290			}
291		}
292	
293		private detachTargetListeners(target: HTMLElement) {
294			for (const event of INPUT_EVENTS) {
295				target.removeEventListener(event, this.updateEventCallback);
296			}
297		}
