306		private getTargetText(target: Node): {
307			text: string | null;
308			isCM: boolean;
309			newLineIndices: number[];
310		} {
311			let text: string | null = null;
312	
313			// Check if it is a CodeMirror instance, which needs to be handled in a specific way.
314			const isCM = target instanceof HTMLElement && getCMRoot(target) != null;
315	
316			if (isCM) {
317				const lineElements = (target as HTMLElement).querySelectorAll<HTMLElement>('.cm-line');
318				const lines = Array.from(lineElements).map((el) => el.textContent);
319				text = lines.reduce((acc: string, x: string | null) => `${acc}${x ?? ''}\n`, '');
320			} else {
321				text =
322					target instanceof HTMLTextAreaElement || target instanceof HTMLInputElement
323						? target.value
324						: (target as HTMLElement).innerText;
325			}
326	
327			const newLineIndices: number[] = [];
328			let i = 0;
329			for (const c of text ?? '') {
330				if (c == '\n') {
331					newLineIndices.push(i);
332				}
333				i++;
334			}
335	
336			return { text, isCM, newLineIndices };
337		}
338	
339		private requestRender() {
340			if (this.renderRequested) {
341				return;
342			}
343	
344			this.renderRequested = true;
345	
346			requestAnimationFrame(() => {
347				const boxes = this.lastLints.flatMap(({ target, lints }) => {
348					if (!target) {
349						return [];
350					}
351	
352					const { text, isCM } = this.getTargetText(target);
353					if (text == null) {
354						return [];
355					}
356	
357					return Object.entries(lints).flatMap(([ruleName, ls]) =>
358						ls.flatMap((lint) => {
359							const currentLint = isCM
360								? lint.source === text
361									? lint
362									: null
363								: remapLintToCurrentSource(lint, text);
364							if (currentLint == null) {
365								return [];
366							}
367	
368							return computeLintBoxes(target, currentLint, ruleName, {
369								ignoreLint: this.actions.ignoreLint
370									? async (hash: string) => {
371											await this.actions.ignoreLint?.(hash);
372											await this.requestLintUpdate(true);
373										}
374									: undefined,
375							});
376						}),
377					);
378				});
379				this.lastLintBoxes = boxes;
380				this.highlights.renderLintBoxes(boxes);
381				this.popupHandler.updateLintBoxes(boxes);
382	
383				this.renderRequested = false;
384				this.lastBoxes = boxes;
385			});
386		}
387	}
