		calls.push(text);
		return new Promise((resolve) => {
			pending.push(() => resolve({}));
		});
	};

	return {
		provider,
		calls,
		/** Complete the oldest outstanding request. */
		async resolveNext() {
			const next = pending.shift();
			if (next == null) {
				throw new Error('No outstanding lint request to resolve.');
			}
			next();
			await tick();
		},
	};
}

const targets: HTMLTextAreaElement[] = [];

