	const el = document.createElement('textarea');
	el.value = value;
	el.style.width = '400px';
	el.style.height = '100px';
	document.body.appendChild(el);
	targets.push(el);
	return el;
}

afterEach(() => {
	for (const el of targets.splice(0)) {
		el.remove();
	}
});

